using System;
using System.IO;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using System.Collections.Generic;
namespace kok {
 public sealed class ContentExtraction {
  readonly object gate=new object();readonly Dictionary<string,TaskCompletionSource<List<ContentPage>>> pending=new Dictionary<string,TaskCompletionSource<List<ContentPage>>>();
  public async Task<List<ContentPage>> Run(ModuleContext c,Entry item,CancellationToken token){var ticket=Guid.NewGuid().ToString("N");var done=new TaskCompletionSource<List<ContentPage>>(TaskCreationOptions.RunContinuationsAsynchronously);lock(gate){if(pending.Count>=2)throw new InvalidOperationException("Another PDF extraction is running.");pending[ticket]=done;}using(var timeout=CancellationTokenSource.CreateLinkedTokenSource(token)){timeout.CancelAfter(90000);using(timeout.Token.Register(()=>done.TrySetCanceled()))try{c.Notify("contentExtract",new{ticket,itemId=item.id});var pages=await done.Task;c.Policy.Ensure(Need.NormalLibrary,"workspace");return pages;}catch(OperationCanceledException){token.ThrowIfCancellationRequested();throw new IOException("PDF extraction timed out; retry this source.");}finally{lock(gate)pending.Remove(ticket);c.Notify("contentExtractCancel",new{ticket});}}}
  public bool Complete(string ticket,List<ContentPage> pages,string error=""){if(!AgentJournal.ValidId(ticket)||pages==null||pages.Count>2000||pages.Any(p=>p==null||p.text==null||p.page<1)||pages.Sum(p=>(long)p.text.Length)>2000000||!new[]{"","failed","limit"}.Contains(error))throw new InvalidDataException("Invalid PDF extraction result.");lock(gate){TaskCompletionSource<List<ContentPage>> done;if(!pending.TryGetValue(ticket,out done))return false;return error==""?done.TrySetResult(pages):done.TrySetException(new IOException("PDF text extraction failed or exceeded its limit."));}}
 }
 public partial class Library {internal readonly ContentExtraction ContentExtractor=new ContentExtraction();}
 internal static class KnowledgeActions {
  static Dictionary<string,object> Obj(string[] required,params object[] fields){return CapabilitySchema.Obj(CapabilitySchema.Fields(fields),required);}
  static Dictionary<string,object> Str(int length){return CapabilitySchema.Str(length);}
  static Dictionary<string,object> Bool(){return new Dictionary<string,object>{{"type","boolean"}};}
  static Dictionary<string,object> Number(int min,int max){return new Dictionary<string,object>{{"type","integer"},{"minimum",min},{"maximum",max}};}
  static Dictionary<string,object> Ids(){return new Dictionary<string,object>{{"type","array"},{"maxItems",10000},{"items",Str(32)}};}
  static Dictionary<string,object> Config(){return Obj(new[]{"enabled","endpoint","model","revision","minimumSimilarity"},"enabled",Bool(),"endpoint",Str(500),"model",Str(200),"revision",Str(100),"minimumSimilarity",new Dictionary<string,object>{{"type","number"},{"minimum",0},{"maximum",1}});}
  internal static IEnumerable<ActionSpec> Actions(){return new[]{
   ModuleDefinitions.Action("contentIndexState",Need.NormalLibrary,false,(c,a)=>Task.FromResult((object)new{sources=c.Library.ContentStatus(),config=c.Library.ReadEmbeddingConfig()}),CapabilitySchema.Obj()),
   ModuleDefinitions.Action("contentExtractResult",Need.NormalLibrary,false,(c,a)=>Task.FromResult((object)c.Library.ContentExtractor.Complete(ModuleContext.Text(a,"ticket"),AgentTaskState.Get<List<ContentPage>>(a,"pages"),ModuleContext.Text(a,"error"))),Obj(new[]{"ticket","pages"},"ticket",Str(32),"pages",new Dictionary<string,object>{{"type","array"},{"maxItems",2000},{"items",Obj(new[]{"page","text"},"page",Number(1,100000),"text",Str(2000000))}},"error",new Dictionary<string,object>{{"type","string"},{"enum",new[]{"","failed","limit"}}})),
   ModuleDefinitions.Action("contentIndexBuild",Need.NormalLibrary,true,Build,Obj(new string[0],"ids",Ids(),"rebuild",Bool())),
   ModuleDefinitions.Action("embeddingSave",Need.NormalLibrary,true,(c,a)=>Task.FromResult((object)c.Library.SaveEmbeddingConfig(AgentTaskState.Get<EmbeddingConfig>(a,"config"))),Obj(new[]{"config"},"config",Config())),
   ModuleDefinitions.Action("embeddingBuild",Need.Ai|Need.NormalLibrary,true,async(c,a)=>{using(c.BeginWrite()){var result=await c.Library.BuildEmbeddings(c.Jobs.CurrentToken,(done,total)=>c.Notify("embeddingProgress",new{completed=done,total}),validate:()=>c.Policy.Ensure(Need.Ai|Need.NormalLibrary,"workspace"));c.Notify("contentIndexChanged",null);return result;}},CapabilitySchema.Obj()),
   ModuleDefinitions.Action("searchKnowledge",Need.NormalLibrary,false,async(c,a)=>{string mode=ModuleContext.Text(a,"mode");if(mode=="")mode="lexical";Action check=()=>c.Policy.Ensure(Need.NormalLibrary|(mode!="lexical"?Need.Ai:Need.None),"workspace");check();var result=await c.Library.SearchKnowledge(ModuleContext.Text(a,"query"),a.ContainsKey("ids")?AgentTaskState.Get<List<string>>(a,"ids"):null,mode,a.ContainsKey("limit")?Convert.ToInt32(a["limit"]):100,c.Token,validate:check);check();return result;},Obj(new[]{"query"},"query",Str(200),"ids",Ids(),"mode",new Dictionary<string,object>{{"type","string"},{"enum",new[]{"lexical","hybrid","semantic"}}},"limit",Number(1,500))),
   ModuleDefinitions.Action("readContentChunk",Need.NormalLibrary,false,(c,a)=>Task.FromResult((object)c.Library.ReadContentChunk(ModuleContext.Text(a,"chunkId"),c.Library.ContentEntries().Select(e=>e.id))),Obj(new[]{"chunkId"},"chunkId",Str(32)))
  }.Concat(KnowledgeTransferActions.Actions()).Concat(ConnectionActions.Actions()).Concat(OcrActions.Actions()).Concat(new[]{ModuleDefinitions.Command("commandLibraryTools","资料检索与备份","workspace.libraryTools",Need.NormalLibrary)});}
  static async Task<object> Build(ModuleContext c,Dictionary<string,object> a){
   var selected=a.ContainsKey("ids")?new HashSet<string>(AgentTaskState.Get<List<string>>(a,"ids")):null;bool rebuild=a.ContainsKey("rebuild")&&Convert.ToBoolean(a["rebuild"]);var entries=c.Library.ContentEntries().Where(e=>selected==null||selected.Contains(e.id)).ToArray();var states=c.Library.ContentStatus().ToDictionary(s=>s.itemId);int done=0,indexed=0,failed=0;using(c.BeginWrite()){foreach(var entry in entries){var token=c.Jobs.CurrentToken;token.ThrowIfCancellationRequested();c.Policy.Ensure(Need.NormalLibrary,"workspace");var status=states[entry.id];if(!rebuild&&new[]{"ready","metadata_only","needs_ocr"}.Contains(status.state)){done++;continue;}string stamp=c.Library.ContentStamp(entry.id);try{List<ContentPage> pages=null;if(entry.ext=="PDF"&&File.Exists(entry.path))pages=await c.Library.ContentExtractor.Run(c,entry,token);c.Policy.Ensure(Need.NormalLibrary,"workspace");token.ThrowIfCancellationRequested();status=await Task.Run(()=>c.Library.IndexContentSource(entry.id,pages,stamp),token);indexed++;if(status.state=="failed")failed++;}catch(IOException){failed++;c.Library.FailContentSource(entry.id,stamp);}catch(InvalidDataException){failed++;c.Library.FailContentSource(entry.id,stamp);}finally{c.Notify("contentIndexProgress",new{completed=++done,total=entries.Length});}}}c.Notify("contentIndexChanged",null);return new{indexed,failed,total=entries.Length};
  }
 }
}
